public class DualWritePublisher
{
    private readonly RabbitMQ.Client.IModel _rabbitChannel;
    private readonly IProducer<string, string> _kafkaProducer;

    public void Publish(string routingKey, string payload)
    {
        // Write to legacy broker
        _rabbitChannel.BasicPublish("orders-exchange", routingKey,
            mandatory: false,
            body: Encoding.UTF8.GetBytes(payload));

        // Write to new broker
        _kafkaProducer.Produce("orders-topic",
            new Message<string, string> { Key = routingKey, Value = payload },
            DeliveryHandler);
    }

    private static void DeliveryHandler(DeliveryReport<string, string> report)
    {
        if (report.Error is not null)
            Console.WriteLine($"Kafka delivery failed: {report.Error.Reason}");
    }
}
